import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import { useConfigurationContext } from "@/components/atomic-crm/root/ConfigurationContext";

interface ContactStatusBadgeProps {
  status: string | null | undefined;
  className?: string;
}

const STATUS_TONE: Record<string, string> = {
  cold: "border-sky-300 bg-sky-50 text-sky-800",
  warm: "border-amber-300 bg-amber-50 text-amber-900",
  hot: "border-red-300 bg-red-50 text-red-800",
  "in-contract": "border-emerald-300 bg-emerald-50 text-emerald-800",
};

/**
 * Small pill that mirrors the contact status colours used by upstream's
 * status configuration but shows the label as a badge rather than a dot
 * on a name — matches the mid-fi wireframe next to contact names.
 */
export function ContactStatusBadge({
  status,
  className,
}: ContactStatusBadgeProps) {
  const { noteStatuses } = useConfigurationContext();
  if (!status) return null;
  const configured = noteStatuses.find((s) => s.value === status);
  const label = configured?.label ?? status;
  return (
    <Badge
      variant="outline"
      className={cn(
        "font-normal capitalize",
        STATUS_TONE[status] ?? "border-muted text-muted-foreground",
        className,
      )}
    >
      {label}
    </Badge>
  );
}
