import { Compass } from "lucide-react";
import { useTranslate } from "ra-core";

import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";

import type { ColorMode } from "./types";

interface Filters {
  onlyMine: boolean;
  segments: Set<"A" | "B" | "C">;
  distrikt: string | null;
  needsVisit: boolean;
  neverVisited: boolean;
  kundestatus: string | null;
}

interface Props {
  colorMode: ColorMode;
  onColorModeChange: (m: ColorMode) => void;
  filters: Filters;
  onFiltersChange: (f: Filters) => void;
  distinctDistrikter: string[];
  distinctStatus: string[];
  nearMeOn: boolean;
  onToggleNearMe: () => void;
  hasMySalesId: boolean;
}

const ALL = "__all__";

export function KortLensPanel({
  colorMode,
  onColorModeChange,
  filters,
  onFiltersChange,
  distinctDistrikter,
  distinctStatus,
  nearMeOn,
  onToggleNearMe,
  hasMySalesId,
}: Props) {
  const translate = useTranslate();
  const toggleSegment = (s: "A" | "B" | "C") => {
    const next = new Set(filters.segments);
    if (next.has(s)) next.delete(s);
    else next.add(s);
    onFiltersChange({ ...filters, segments: next });
  };

  return (
    <div className="flex flex-col gap-4 p-3">
      <div>
        <div className="text-muted-foreground mb-2 text-[10px] font-medium uppercase tracking-widest">
          {translate("lago.felt.kort.color_mode_label")}
        </div>
        <div className="flex flex-wrap gap-1">
          <ModeChip
            on={colorMode === "priority"}
            onClick={() => onColorModeChange("priority")}
            label={translate("lago.felt.kort.color_priority")}
          />
          <ModeChip
            on={colorMode === "segment"}
            onClick={() => onColorModeChange("segment")}
            label={translate("lago.felt.kort.color_segment")}
          />
          <ModeChip
            on={colorMode === "status"}
            onClick={() => onColorModeChange("status")}
            label={translate("lago.felt.kort.color_status")}
          />
        </div>
      </div>

      <div>
        <div className="text-muted-foreground mb-2 text-[10px] font-medium uppercase tracking-widest">
          {translate("lago.felt.kort.lenses_label")}
        </div>
        <div className="flex flex-col gap-1.5 text-xs">
          <Toggle
            checked={filters.onlyMine}
            disabled={!hasMySalesId}
            onChange={(v) => onFiltersChange({ ...filters, onlyMine: v })}
            label={translate("lago.customer_list.filter_mine")}
          />
          <Toggle
            checked={filters.needsVisit}
            onChange={(v) => onFiltersChange({ ...filters, needsVisit: v })}
            label={translate("lago.customer_list.filter_needs_visit")}
          />
          <Toggle
            checked={filters.neverVisited}
            onChange={(v) => onFiltersChange({ ...filters, neverVisited: v })}
            label={translate("lago.customer_list.filter_visit_never")}
          />
        </div>
      </div>

      <div>
        <div className="text-muted-foreground mb-2 text-[10px] font-medium uppercase tracking-widest">
          Segment
        </div>
        <div className="flex gap-1">
          {(["A", "B", "C"] as const).map((s) => (
            <Button
              key={s}
              size="sm"
              variant={filters.segments.has(s) ? "default" : "outline"}
              className="h-7 flex-1 text-xs"
              onClick={() => toggleSegment(s)}
            >
              {s}
            </Button>
          ))}
        </div>
      </div>

      <div>
        <div className="text-muted-foreground mb-1 text-[10px] font-medium uppercase tracking-widest">
          {translate("lago.customer_list.filter_district_label")}
        </div>
        <Select
          value={filters.distrikt ?? ALL}
          onValueChange={(v) =>
            onFiltersChange({ ...filters, distrikt: v === ALL ? null : v })
          }
        >
          <SelectTrigger className="h-8 text-xs">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value={ALL}>
              {translate("lago.customer_list.filter_district_all")}
            </SelectItem>
            {distinctDistrikter.map((d) => (
              <SelectItem key={d} value={d}>
                {d}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div>
        <div className="text-muted-foreground mb-1 text-[10px] font-medium uppercase tracking-widest">
          Kundestatus
        </div>
        <Select
          value={filters.kundestatus ?? ALL}
          onValueChange={(v) =>
            onFiltersChange({
              ...filters,
              kundestatus: v === ALL ? null : v,
            })
          }
        >
          <SelectTrigger className="h-8 text-xs">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value={ALL}>Alle</SelectItem>
            {distinctStatus.map((s) => (
              <SelectItem key={s} value={s}>
                {s}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <Button
        onClick={onToggleNearMe}
        variant={nearMeOn ? "default" : "outline"}
        className="mt-auto h-9 justify-start gap-2 text-sm"
      >
        <Compass className="h-4 w-4" />
        {nearMeOn
          ? translate("lago.felt.kort.near_me_off")
          : translate("lago.felt.kort.near_me")}
      </Button>
    </div>
  );
}

function ModeChip({
  on,
  onClick,
  label,
}: {
  on: boolean;
  onClick: () => void;
  label: string;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "rounded-full border px-2.5 py-1 text-[11px] font-medium",
        on ? "bg-foreground text-background border-foreground" : "border-border",
      )}
    >
      {label}
    </button>
  );
}

function Toggle({
  checked,
  onChange,
  label,
  disabled,
}: {
  checked: boolean;
  onChange: (v: boolean) => void;
  label: string;
  disabled?: boolean;
}) {
  return (
    <label
      className={cn(
        "flex items-center gap-2",
        disabled && "text-muted-foreground opacity-60",
      )}
    >
      <input
        type="checkbox"
        checked={checked}
        disabled={disabled}
        onChange={(e) => onChange(e.target.checked)}
      />
      {label}
    </label>
  );
}
