import { useTranslate } from "ra-core";

import {
  ContactList,
  ContactListMobile,
} from "@/components/atomic-crm/contacts/ContactList";
import { useIsMobile } from "@/hooks/use-mobile";

/**
 * LAGO wrapper for the contact list. Deliberately thin — we keep the
 * full Atomic surface (filters, tags, status, account manager, bulk
 * actions, CSV import/export, sort) intact. The wrapper only adds a
 * LAGO-typographic page title so the surface feels consistent with the
 * customer list and dashboard. Everything else routes through upstream.
 */
export function LagoContactList() {
  const translate = useTranslate();
  const isMobile = useIsMobile();
  return (
    <div className="mx-auto max-w-screen-2xl">
      {!isMobile && (
        <header className="px-4 pt-4">
          <h1 className="text-lg font-semibold">
            {translate("lago.contact.title")}
          </h1>
        </header>
      )}
      {isMobile ? <ContactListMobile /> : <ContactList />}
    </div>
  );
}
