import {
  ArrowRight,
  MapPin,
  Navigation,
  Phone,
  User,
} from "lucide-react";
import { Link } from "react-router-dom";
import { useTranslate } from "ra-core";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { cn } from "@/lib/utils";

import type { VisitStatus } from "@/lago/customers/priority";
import { RegistrerButton } from "@/lago/registrer/RegistrerButton";
import { useSellerLookup } from "@/lago/settings/useSellerLookup";

import type { FeltCustomer } from "./dataAccess";

interface CustomerCardProps {
  customer: FeltCustomer;
  variant?: "grid" | "list";
}

function dotClass(status: VisitStatus): string {
  switch (status) {
    case "overdue":
      return "bg-red-500";
    case "soon":
      return "bg-amber-500";
    case "on_plan":
      return "bg-emerald-500";
    case "never_visited":
    default:
      return "bg-muted-foreground/40";
  }
}

function lastVisitPhrase(
  customer: FeltCustomer,
  translate: ReturnType<typeof useTranslate>,
): string {
  const days = customer.priority.daysSinceVisit;
  if (days == null) return translate("lago.customer_list.never_visited_soft");
  if (days <= 0) return translate("lago.customer_list.last_visit_today");
  if (days === 1) return translate("lago.customer_list.last_visit_yesterday");
  return translate("lago.customer_list.last_visit_n_days_ago", { n: days });
}

function buildMapsUrl(customer: FeltCustomer): string | null {
  const parts = [
    customer.address,
    customer.zipcode,
    customer.city,
    "Danmark",
  ].filter(Boolean);
  if (parts.length === 0) return null;
  const q = encodeURIComponent(parts.join(", "));
  // maps.apple.com auto-redirects to Google Maps / native app on Android.
  // Same URL works on iOS Safari + macOS + Windows browsers.
  return `https://maps.apple.com/?q=${q}`;
}

/**
 * The single card-anatomy used across the felt-flade — Dagens grid, Søg
 * preview, and (later) the map pin popover. See
 * `LAGO_Design_felt-salgs-kundeflade.html#kort-design` for the pattern.
 *
 * The four quick-actions at the bottom follow the design: Naviger · Ring ·
 * Besøgt (primary) · Åbn. Minimum 56px hit targets on iPad; buttons keep
 * a stable stacked-icon layout so muscle memory works in the field.
 */
export function CustomerCard({
  customer,
  variant = "grid",
}: CustomerCardProps) {
  const translate = useTranslate();
  const segment = customer.extension?.segment;
  const distrikt = customer.extension?.distrikt;
  const sellers = useSellerLookup();
  const salesName =
    sellers.byCode(customer.extension?.visma_sales_code) ??
    customer.extension?.visma_sales_name ??
    null;
  const mapsUrl = buildMapsUrl(customer);
  const telHref = customer.phone_number ? `tel:${customer.phone_number}` : null;
  const noteQuote = customer.latestActivityDescription;
  const activityType = customer.latestActivityType;

  return (
    <Card className={cn(variant === "list" ? "" : "flex h-full flex-col")}>
      <CardContent
        className={cn(
          "flex flex-col gap-3 p-4",
          variant === "list" ? "" : "flex-1",
        )}
      >
        <div className="flex items-start gap-2">
          <span
            aria-hidden
            className={cn(
              "mt-2 h-2 w-2 flex-shrink-0 rounded-full",
              dotClass(customer.priority.status),
            )}
          />
          <div className="min-w-0 flex-1">
            <div className="text-[15px] font-semibold leading-tight truncate">
              {customer.name}
            </div>
            <div className="text-muted-foreground truncate text-xs">
              {[customer.address, customer.zipcode, customer.city]
                .filter(Boolean)
                .join(", ") || "—"}
            </div>
          </div>
          {segment && (
            <Badge
              variant="secondary"
              className="flex-shrink-0 font-normal"
            >
              {segment}
            </Badge>
          )}
          {distrikt && (
            <Badge
              variant="outline"
              className="flex-shrink-0 font-normal text-[10px]"
            >
              {distrikt}
            </Badge>
          )}
        </div>

        <div className="text-muted-foreground flex flex-wrap items-center gap-x-2 gap-y-0.5 text-xs">
          <span className="inline-flex items-center gap-1">
            <span
              aria-hidden
              className={cn(
                "h-1.5 w-1.5 rounded-full",
                dotClass(customer.priority.status),
              )}
            />
            {lastVisitPhrase(customer, translate)}
          </span>
          {salesName && (
            <>
              <span aria-hidden>·</span>
              <span className="inline-flex items-center gap-1">
                <User className="h-3 w-3" />
                {salesName}
              </span>
            </>
          )}
          {customer.city && (
            <>
              <span aria-hidden>·</span>
              <span className="inline-flex items-center gap-1">
                <MapPin className="h-3 w-3" />
                {customer.city}
              </span>
            </>
          )}
        </div>

        <div className="text-muted-foreground text-xs italic">
          {noteQuote ? (
            <>
              {activityType && activityType !== "Besøg" && (
                <span className="mr-1 not-italic">[{activityType}]</span>
              )}
              {translate("lago.felt.card.note_quote_prefix")}
              {noteQuote}
              {translate("lago.felt.card.note_quote_suffix")}
            </>
          ) : (
            <span>{translate("lago.felt.card.no_note_yet")}</span>
          )}
        </div>

        <div className="mt-auto grid grid-cols-4 gap-1.5">
          <QuickAction
            href={mapsUrl}
            label={translate("lago.felt.card.action_navigate")}
            icon={<Navigation className="h-4 w-4" />}
          />
          <QuickAction
            href={telHref}
            label={translate("lago.felt.card.action_call")}
            icon={<Phone className="h-4 w-4" />}
            disabledTitle={
              !telHref ? translate("lago.felt.card.no_phone") : undefined
            }
          />
          <RegistrerButton
            variant="card"
            companyId={customer.id}
            companyName={customer.name}
          />
          <Button
            asChild
            variant="outline"
            className="flex h-14 flex-col gap-0.5 rounded-md px-2 py-1 text-[11px]"
          >
            <Link to={`/companies/${customer.id}/show`}>
              <ArrowRight className="h-4 w-4" />
              <span>{translate("lago.felt.card.action_open")}</span>
            </Link>
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

interface QuickActionProps {
  href: string | null;
  label: string;
  icon: React.ReactNode;
  disabledTitle?: string;
}

function QuickAction({ href, label, icon, disabledTitle }: QuickActionProps) {
  if (!href) {
    return (
      <Button
        variant="outline"
        className="flex h-14 flex-col gap-0.5 rounded-md px-2 py-1 text-[11px]"
        disabled
        title={disabledTitle}
      >
        {icon}
        <span>{label}</span>
      </Button>
    );
  }
  return (
    <Button
      asChild
      variant="outline"
      className="flex h-14 flex-col gap-0.5 rounded-md px-2 py-1 text-[11px]"
    >
      <a href={href} target={href.startsWith("tel:") ? undefined : "_blank"} rel="noreferrer">
        {icon}
        <span>{label}</span>
      </a>
    </Button>
  );
}
