import { useQuery } from "@tanstack/react-query";
import { getSupabaseClient } from "@/components/atomic-crm/providers/supabase/supabase";
import { Building2, Loader2, Search, StickyNote, User, Users } from "lucide-react";
import { useDeferredValue, useEffect, useMemo, useRef, useState } from "react";
import { Link } from "react-router-dom";
import { useTranslate } from "ra-core";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { cn } from "@/lib/utils";

import { useSellerLookup } from "@/lago/settings/useSellerLookup";
import { useVisitIntervals } from "@/lago/settings/useVisitIntervals";

import { CustomerCard } from "./CustomerCard";
import { fetchFeltCustomers, type FeltCustomer } from "./dataAccess";

type Scope = "customers" | "contacts" | "notes";

interface ContactHit {
  id: number;
  first_name: string | null;
  last_name: string | null;
  title: string | null;
  status: string | null;
  company_id: number | null;
  company_name: string | null;
  email: string | null;
}

interface NoteHit {
  id: number;
  company_id: number;
  company_name: string | null;
  activity_date: string;
  activity_type: string | null;
  description: string;
}

/**
 * Domain-brief 9 · Fase A — Søg. The full 251-customer base lives here
 * as a search surface, never as a default scroll. Three scope-chips
 * (Kunder / Kontakter / Noter) share the same search input; the felt
 * card-anatomy renders the preview on the right in landscape, stacked
 * below results in portrait.
 */
export function SoegPage() {
  const translate = useTranslate();

  const inputRef = useRef<HTMLInputElement | null>(null);
  const [scope, setScope] = useState<Scope>("customers");
  const [q, setQ] = useState("");
  const deferredQ = useDeferredValue(q);
  const [selectedCustomerId, setSelectedCustomerId] = useState<number | null>(
    null,
  );

  // ⌘K / Ctrl+K focuses the search input from anywhere on the felt-flade.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        e.preventDefault();
        inputRef.current?.focus();
        inputRef.current?.select();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  const intervals = useVisitIntervals();
  const customersQuery = useQuery({
    queryKey: [
      "lago-felt-customers",
      { onlyMine: false, mySalesId: null, intervals },
    ],
    queryFn: () =>
      fetchFeltCustomers({ mySalesId: null, onlyMine: false, intervals }),
    enabled: scope === "customers" || selectedCustomerId != null,
  });

  const contactsQuery = useQuery({
    queryKey: ["lago-soeg-contacts", deferredQ],
    queryFn: () => searchContacts(deferredQ),
    enabled: scope === "contacts" && deferredQ.trim().length >= 2,
  });

  const notesQuery = useQuery({
    queryKey: ["lago-soeg-notes", deferredQ],
    queryFn: () => searchNotes(deferredQ),
    enabled: scope === "notes" && deferredQ.trim().length >= 2,
  });

  const customerHits = useMemo<FeltCustomer[]>(() => {
    if (scope !== "customers") return [];
    const rows = customersQuery.data ?? [];
    const needle = deferredQ.trim().toLowerCase();
    if (!needle) return rows.slice(0, 50);
    return rows
      .filter((r) => {
        const hay =
          `${r.name} ${r.city ?? ""} ${r.extension?.visma_customer_no ?? ""}`.toLowerCase();
        return hay.includes(needle);
      })
      .slice(0, 50);
  }, [scope, customersQuery.data, deferredQ]);

  const selectedCustomer = useMemo(() => {
    if (selectedCustomerId == null) return null;
    return (customersQuery.data ?? []).find((c) => c.id === selectedCustomerId) ?? null;
  }, [customersQuery.data, selectedCustomerId]);

  const showShortcuts = deferredQ.trim().length === 0 && scope === "customers";

  return (
    <div className="mx-auto max-w-screen-2xl px-4 py-6">
      <div className="mb-4 flex items-center gap-3">
        <div className="border-border relative flex-1 rounded-md border bg-background">
          <Search className="text-muted-foreground pointer-events-none absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2" />
          <input
            ref={inputRef}
            type="search"
            value={q}
            autoFocus
            onChange={(e) => setQ(e.target.value)}
            placeholder={translate("lago.felt.soeg.placeholder")}
            className="w-full bg-transparent py-3 pl-10 pr-16 text-base outline-none"
          />
          <span className="border-border text-muted-foreground pointer-events-none absolute top-1/2 right-3 -translate-y-1/2 rounded border bg-muted px-1.5 py-0.5 text-[10px]">
            {translate("lago.felt.soeg.keyboard_hint")}
          </span>
        </div>
        <Button variant="outline" asChild size="sm">
          <Link to="/companies">{translate("lago.felt.soeg.table_view")} →</Link>
        </Button>
      </div>

      <div className="mb-4 flex flex-wrap gap-2">
        <ScopeChip
          active={scope === "customers"}
          onClick={() => setScope("customers")}
          icon={<Building2 className="h-3.5 w-3.5" />}
          label={translate("lago.felt.soeg.scope_customers")}
        />
        <ScopeChip
          active={scope === "contacts"}
          onClick={() => setScope("contacts")}
          icon={<Users className="h-3.5 w-3.5" />}
          label={translate("lago.felt.soeg.scope_contacts")}
        />
        <ScopeChip
          active={scope === "notes"}
          onClick={() => setScope("notes")}
          icon={<StickyNote className="h-3.5 w-3.5" />}
          label={translate("lago.felt.soeg.scope_notes")}
        />
      </div>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        <div>
          {showShortcuts && (
            <ShortcutStrip
              onNeedsVisit={() => setQ("")}
              onMine={() => setQ("")}
              onNever={() => setQ("")}
            />
          )}
          {scope === "customers" && (
            <CustomerHits
              q={deferredQ}
              loading={customersQuery.isLoading}
              rows={customerHits}
              selectedId={selectedCustomerId}
              onSelect={setSelectedCustomerId}
            />
          )}
          {scope === "contacts" && (
            <ContactHits
              q={deferredQ}
              loading={contactsQuery.isLoading}
              rows={contactsQuery.data ?? []}
              onOpenCustomer={setSelectedCustomerId}
            />
          )}
          {scope === "notes" && (
            <NoteHits
              q={deferredQ}
              loading={notesQuery.isLoading}
              rows={notesQuery.data ?? []}
              onOpenCustomer={setSelectedCustomerId}
            />
          )}
        </div>
        <div>
          <div className="text-muted-foreground mb-2 text-xs uppercase tracking-widest">
            Preview
          </div>
          {selectedCustomer ? (
            <CustomerCard customer={selectedCustomer} variant="list" />
          ) : (
            <div className="text-muted-foreground rounded-md border border-dashed p-8 text-center text-sm">
              {translate("lago.felt.soeg.preview_placeholder")}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function ScopeChip({
  active,
  onClick,
  icon,
  label,
}: {
  active: boolean;
  onClick: () => void;
  icon: React.ReactNode;
  label: string;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "border-border inline-flex items-center gap-1.5 rounded-full border px-3 py-1 text-xs transition-colors",
        active
          ? "bg-foreground text-background border-foreground"
          : "hover:bg-muted bg-background",
      )}
    >
      {icon}
      {label}
    </button>
  );
}

function ShortcutStrip({
  onNeedsVisit,
  onMine,
  onNever,
}: {
  onNeedsVisit: () => void;
  onMine: () => void;
  onNever: () => void;
}) {
  const translate = useTranslate();
  return (
    <div className="mb-4 rounded-md border border-dashed p-4">
      <p className="text-muted-foreground mb-3 text-sm">
        {translate("lago.felt.soeg.empty_hint")}
      </p>
      <div className="flex flex-wrap gap-2">
        <Button size="sm" variant="secondary" onClick={onMine}>
          {translate("lago.felt.soeg.shortcut_mine")}
        </Button>
        <Button size="sm" variant="secondary" onClick={onNeedsVisit}>
          {translate("lago.felt.soeg.shortcut_needs_visit")}
        </Button>
        <Button size="sm" variant="secondary" onClick={onNever}>
          {translate("lago.felt.soeg.shortcut_never_visited")}
        </Button>
      </div>
    </div>
  );
}

function CustomerHits({
  q,
  loading,
  rows,
  selectedId,
  onSelect,
}: {
  q: string;
  loading: boolean;
  rows: FeltCustomer[];
  selectedId: number | null;
  onSelect: (id: number) => void;
}) {
  const translate = useTranslate();
  const sellers = useSellerLookup();
  if (loading) return <Skeleton />;
  if (rows.length === 0) return <NoResults q={q} />;
  return (
    <>
      <div className="text-muted-foreground mb-2 text-xs">
        {translate("lago.felt.soeg.results_customers", {
          smart_count: rows.length,
          n: rows.length,
        })}
      </div>
      <ul className="space-y-2">
        {rows.map((r) => (
          <li key={r.id}>
            <button
              type="button"
              onClick={() => onSelect(r.id)}
              className={cn(
                "block w-full text-left focus-visible:outline-none",
                selectedId === r.id && "ring-primary rounded-md ring-2 ring-offset-1",
              )}
            >
              <Card className="hover:bg-muted/40 transition-colors">
                <CardContent className="flex items-center gap-3 py-3">
                  <div className="min-w-0 flex-1">
                    <div className="truncate text-sm font-semibold">{r.name}</div>
                    <div className="text-muted-foreground text-xs">
                      {[r.city, r.extension?.distrikt].filter(Boolean).join(" · ")}
                      {(() => {
                        const s =
                          sellers.byCode(r.extension?.visma_sales_code) ??
                          r.extension?.visma_sales_name ??
                          null;
                        return s ? ` · ${s}` : null;
                      })()}
                    </div>
                  </div>
                  {r.extension?.segment && (
                    <Badge variant="secondary" className="font-normal">
                      {r.extension.segment}
                    </Badge>
                  )}
                </CardContent>
              </Card>
            </button>
          </li>
        ))}
      </ul>
    </>
  );
}

function ContactHits({
  q,
  loading,
  rows,
  onOpenCustomer,
}: {
  q: string;
  loading: boolean;
  rows: ContactHit[];
  onOpenCustomer: (id: number | null) => void;
}) {
  const translate = useTranslate();
  if (q.trim().length < 2)
    return <HintTooShort />;
  if (loading) return <Skeleton />;
  if (rows.length === 0) return <NoResults q={q} />;
  return (
    <>
      <div className="text-muted-foreground mb-2 text-xs">
        {translate("lago.felt.soeg.results_contacts", {
          smart_count: rows.length,
          n: rows.length,
        })}
      </div>
      <ul className="space-y-2">
        {rows.map((r) => {
          const full = `${r.first_name ?? ""} ${r.last_name ?? ""}`.trim() || "—";
          return (
            <li key={r.id}>
              <Card>
                <CardContent className="flex items-center gap-3 py-3">
                  <User className="text-muted-foreground h-4 w-4" />
                  <div className="min-w-0 flex-1">
                    <div className="truncate text-sm font-semibold">{full}</div>
                    <div className="text-muted-foreground text-xs">
                      {r.title && <span>{r.title} · </span>}
                      {r.company_name && (
                        <button
                          type="button"
                          className="underline-offset-2 hover:underline"
                          onClick={() => onOpenCustomer(r.company_id)}
                        >
                          Arbejder hos {r.company_name}
                        </button>
                      )}
                    </div>
                  </div>
                  <Button asChild variant="outline" size="sm">
                    <Link to={`/contacts/${r.id}/show`}>Åbn</Link>
                  </Button>
                </CardContent>
              </Card>
            </li>
          );
        })}
      </ul>
    </>
  );
}

function NoteHits({
  q,
  loading,
  rows,
  onOpenCustomer,
}: {
  q: string;
  loading: boolean;
  rows: NoteHit[];
  onOpenCustomer: (id: number | null) => void;
}) {
  const translate = useTranslate();
  if (q.trim().length < 2)
    return <HintTooShort />;
  if (loading) return <Skeleton />;
  if (rows.length === 0) return <NoResults q={q} />;
  return (
    <>
      <div className="text-muted-foreground mb-2 text-xs">
        {translate("lago.felt.soeg.results_notes", {
          smart_count: rows.length,
          n: rows.length,
        })}
      </div>
      <ul className="space-y-2">
        {rows.map((r) => (
          <li key={r.id}>
            <Card>
              <CardContent className="py-3">
                <div className="text-muted-foreground text-xs">
                  {new Date(r.activity_date).toLocaleDateString("da-DK", {
                    day: "numeric",
                    month: "short",
                    year: "numeric",
                  })}
                  {r.activity_type && ` · ${r.activity_type}`}
                  {r.company_name && (
                    <>
                      {" · "}
                      <button
                        type="button"
                        className="underline-offset-2 hover:underline"
                        onClick={() => onOpenCustomer(r.company_id)}
                      >
                        {r.company_name}
                      </button>
                    </>
                  )}
                </div>
                <div className="text-sm">{r.description}</div>
              </CardContent>
            </Card>
          </li>
        ))}
      </ul>
    </>
  );
}

function Skeleton() {
  return (
    <div className="text-muted-foreground flex items-center gap-2 py-4 text-sm">
      <Loader2 className="h-4 w-4 animate-spin" /> …
    </div>
  );
}

function HintTooShort() {
  return (
    <p className="text-muted-foreground py-4 text-sm">
      Skriv mindst 2 tegn for at søge.
    </p>
  );
}

function NoResults({ q }: { q: string }) {
  const translate = useTranslate();
  return (
    <p className="text-muted-foreground py-4 text-sm">
      {translate("lago.felt.soeg.no_results", { q })}
    </p>
  );
}

async function searchContacts(q: string): Promise<ContactHit[]> {
  const needle = q.trim();
  if (needle.length < 2) return [];
  const supabase = getSupabaseClient();
  const { data, error } = await supabase
    .from("contacts_summary")
    .select("id, first_name, last_name, title, status, company_id, company_name, email_fts")
    .or(`first_name.ilike.%${needle}%,last_name.ilike.%${needle}%,company_name.ilike.%${needle}%`)
    .limit(30);
  if (error) throw error;
  return (data ?? []).map((row: any) => ({
    id: row.id,
    first_name: row.first_name,
    last_name: row.last_name,
    title: row.title,
    status: row.status,
    company_id: row.company_id,
    company_name: row.company_name,
    email: null,
  }));
}

async function searchNotes(q: string): Promise<NoteHit[]> {
  const needle = q.trim();
  if (needle.length < 2) return [];
  const supabase = getSupabaseClient();
  const { data, error } = await supabase
    .from("customer_activities_lago")
    .select("id, company_id, activity_date, activity_type, description, companies!inner(name)")
    .ilike("description", `%${needle}%`)
    .order("activity_date", { ascending: false })
    .limit(30);
  if (error) throw error;
  return (data ?? []).map((row: any) => ({
    id: row.id,
    company_id: row.company_id,
    activity_date: row.activity_date,
    activity_type: row.activity_type,
    description: row.description,
    company_name: row.companies?.name ?? null,
  }));
}
