import {
  FileText,
  Handshake,
  Home,
  Import,
  Settings,
  SlidersHorizontal,
  Target,
  TrendingUp,
  User,
  Users,
  Users2,
} from "lucide-react";
import { CanAccess, useTranslate, useUserMenu } from "ra-core";
import { Link, matchPath, useLocation } from "react-router";
import { RefreshButton } from "@/components/admin/refresh-button";
import { ThemeModeToggle } from "@/components/admin/theme-mode-toggle";
import { UserMenu } from "@/components/admin/user-menu";
import { DropdownMenuItem } from "@/components/ui/dropdown-menu";

import { useConfigurationContext } from "@/components/atomic-crm/root/ConfigurationContext";
import { ImportPage } from "@/components/atomic-crm/misc/ImportPage";
import { ChangelogPage } from "@/components/atomic-crm/misc/ChangelogPage";

import { useIsLagoAdmin } from "@/lago/auth/useIsLagoAdmin";

import { cn } from "@/lib/utils";

/**
 * LAGO topnav (Domain-brief 3e). Same visual shell as upstream's Header
 * but the tab order and labels are LAGO's:
 * Hjem · Kunder · Kontakter · Salgsudvikling · Aftaler (dæmpet).
 * "Aftaler" is deliberately kept — visually toned down until the pipeline
 * is relevant to the field-test — never hidden.
 */
export function LagoHeader() {
  const { darkModeLogo, lightModeLogo, title } = useConfigurationContext();
  const location = useLocation();
  const translate = useTranslate();
  const { isAdmin } = useIsLagoAdmin();

  const currentPath = detectCurrentPath(location.pathname);

  return (
    <nav className="grow">
      <header className="bg-secondary">
        <div className="px-4">
          <div className="flex flex-1 items-center justify-between">
            <Link
              to="/"
              className="text-secondary-foreground flex items-center gap-2 no-underline"
            >
              <img
                className="h-6 [.light_&]:hidden"
                src={darkModeLogo}
                alt={title}
              />
              <img
                className="h-6 [.dark_&]:hidden"
                src={lightModeLogo}
                alt={title}
              />
              <h1 className="text-xl font-semibold">{title}</h1>
            </Link>
            <nav className="flex">
              <NavTab
                to="/felt/dagens"
                icon={<Target className="h-4 w-4" />}
                label={translate("lago.nav.felt")}
                isActive={currentPath === "/felt"}
                title={translate("lago.nav.felt_hint")}
              />
              <NavTab
                to="/"
                icon={<Home className="h-4 w-4" />}
                label={translate("lago.nav.home")}
                isActive={currentPath === "/"}
              />
              <NavTab
                to="/companies"
                icon={<Users2 className="h-4 w-4" />}
                label={translate("lago.nav.customers")}
                isActive={currentPath === "/companies"}
              />
              <NavTab
                to="/contacts"
                icon={<Users className="h-4 w-4" />}
                label={translate("lago.nav.contacts")}
                isActive={currentPath === "/contacts"}
              />
              <NavTab
                to="/salgsudvikling"
                icon={<TrendingUp className="h-4 w-4" />}
                label={translate("lago.nav.sales_dev")}
                isActive={currentPath === "/salgsudvikling"}
              />
              <NavTab
                to="/deals"
                icon={<Handshake className="h-4 w-4" />}
                label={translate("lago.nav.deals")}
                isActive={currentPath === "/deals"}
                muted
                title={translate("lago.nav.deals_muted_hint")}
              />
              {isAdmin && (
                <NavTab
                  to="/indstillinger"
                  icon={<SlidersHorizontal className="h-4 w-4" />}
                  label={translate("lago.nav.settings")}
                  isActive={currentPath === "/indstillinger"}
                  title={translate("lago.nav.settings_hint")}
                />
              )}
            </nav>
            <div className="flex items-center">
              <ThemeModeToggle />
              <RefreshButton />
              <UserMenu>
                <ProfileMenu />
                <CanAccess resource="sales" action="list">
                  <UsersMenu />
                </CanAccess>
                <CanAccess resource="configuration" action="edit">
                  <SettingsMenu />
                </CanAccess>
                <ImportFromJsonMenuItem />
                <ChangelogMenuItem />
              </UserMenu>
            </div>
          </div>
        </div>
      </header>
    </nav>
  );
}

function detectCurrentPath(pathname: string): string | false {
  if (matchPath("/felt/*", pathname)) return "/felt";
  if (matchPath("/contacts/*", pathname)) return "/contacts";
  if (matchPath("/companies/*", pathname)) return "/companies";
  if (matchPath("/deals/*", pathname)) return "/deals";
  if (matchPath("/salgsudvikling/*", pathname)) return "/salgsudvikling";
  if (matchPath("/indstillinger/*", pathname)) return "/indstillinger";
  if (matchPath("/", pathname)) return "/";
  return false;
}

interface NavTabProps {
  to: string;
  icon: React.ReactNode;
  label: string;
  isActive: boolean;
  muted?: boolean;
  title?: string;
}

function NavTab({ to, icon, label, isActive, muted, title }: NavTabProps) {
  return (
    <Link
      to={to}
      title={title}
      className={cn(
        "inline-flex items-center gap-2 border-b-2 px-4 py-3 text-sm font-medium transition-colors sm:px-6",
        isActive
          ? "text-secondary-foreground border-secondary-foreground"
          : "text-secondary-foreground/70 hover:text-secondary-foreground/80 border-transparent",
        muted && "opacity-60 hover:opacity-90",
      )}
    >
      {icon}
      <span className={muted ? "italic" : undefined}>{label}</span>
    </Link>
  );
}

function UsersMenu() {
  const translate = useTranslate();
  const userMenuContext = useUserMenu();
  if (!userMenuContext) {
    throw new Error("<UsersMenu> must be used inside <UserMenu>");
  }
  return (
    <DropdownMenuItem asChild onClick={userMenuContext.onClose}>
      <Link to="/sales" className="flex items-center gap-2">
        <Users />
        {translate("resources.sales.name", { smart_count: 2 })}
      </Link>
    </DropdownMenuItem>
  );
}

