import { useQuery } from "@tanstack/react-query";
import { AlertCircle, CalendarClock, Loader2, Sparkles } from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import { useGetIdentity, useTranslate } from "ra-core";

import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";

import { comparePriority } from "@/lago/customers/priority";
import { useVisitIntervals } from "@/lago/settings/useVisitIntervals";

import { CustomerCard } from "./CustomerCard";
import { fetchFeltCustomers, type FeltCustomer } from "./dataAccess";

const ALL_SENTINEL = "__all__";
type Lens = "needs_now" | "planned_today" | "never_visited";
type SortMode = "most_overdue" | "alpha" | "last_visit";

// Progressive load: render an initial batch, then reveal another batch
// each time the sentinel scrolls into view. Keeps first paint cheap
// while still letting sælger arbejde hele den prioriterede liste igennem.
const INITIAL_BATCH = 12;
const BATCH_STEP = 12;

function formatToday(): string {
  return new Intl.DateTimeFormat("da-DK", {
    weekday: "long",
    day: "numeric",
    month: "long",
  }).format(new Date());
}

/**
 * Domain-brief 9 · Fase A — Dagens/Prioritet. Large glanceable cards on
 * real data. Three lenses (Trænger nu / Planlagt i dag / Aldrig besøgt)
 * plus sælger, distrikt and sort pickers. Not a table — the card grid
 * is the interaction surface.
 */
export function DagensPage() {
  const translate = useTranslate();
  const { data: identity } = useGetIdentity();
  const mySalesId = typeof identity?.id === "number" ? identity.id : null;

  const [lens, setLens] = useState<Lens>("needs_now");
  const [onlyMine, setOnlyMine] = useState(false);
  const [distrikt, setDistrikt] = useState<string>(ALL_SENTINEL);
  const [salesName, setSalesName] = useState<string>(ALL_SENTINEL);
  const [sortMode, setSortMode] = useState<SortMode>("most_overdue");

  const intervals = useVisitIntervals();
  const query = useQuery({
    queryKey: ["lago-felt-customers", { onlyMine, mySalesId, intervals }],
    queryFn: () => fetchFeltCustomers({ mySalesId, onlyMine, intervals }),
  });

  const distinctDistrikter = useMemo(() => {
    const s = new Set<string>();
    for (const r of query.data ?? []) {
      if (r.extension?.distrikt) s.add(r.extension.distrikt);
    }
    return [...s].sort((a, b) => a.localeCompare(b, "da"));
  }, [query.data]);

  const distinctSales = useMemo(() => {
    const s = new Set<string>();
    for (const r of query.data ?? []) {
      if (r.extension?.visma_sales_name) s.add(r.extension.visma_sales_name);
    }
    return [...s].sort((a, b) => a.localeCompare(b, "da"));
  }, [query.data]);

  const counts = useMemo(() => {
    const c = { needs_now: 0, planned_today: 0, never_visited: 0 };
    if (!query.data) return c;
    const todayIso = new Date().toISOString().slice(0, 10);
    for (const r of query.data) {
      if (r.priority.status === "never_visited") c.never_visited++;
      else if (
        r.priority.status === "overdue" ||
        r.priority.status === "soon"
      )
        c.needs_now++;
      if (r.extension?.visma_customer_no && r.priority) {
        // no explicit planned-today source yet, fall through
      }
      const nextVisit = null; // TODO: hook up companies_lago.next_visit_planned when it lands here
      if (nextVisit && String(nextVisit).slice(0, 10) === todayIso)
        c.planned_today++;
    }
    return c;
  }, [query.data]);

  const filtered = useMemo<FeltCustomer[]>(() => {
    if (!query.data) return [];
    return query.data.filter((r) => {
      if (
        distrikt !== ALL_SENTINEL &&
        r.extension?.distrikt !== distrikt
      )
        return false;
      if (
        salesName !== ALL_SENTINEL &&
        r.extension?.visma_sales_name !== salesName
      )
        return false;
      if (lens === "needs_now") {
        return (
          r.priority.status === "overdue" || r.priority.status === "soon"
        );
      }
      if (lens === "planned_today") {
        // No planned-today source yet — brief 9 Fase A ships the lens
        // shell; upstream data lands with future brief.
        return false;
      }
      if (lens === "never_visited") {
        return r.priority.status === "never_visited";
      }
      return true;
    });
  }, [query.data, lens, distrikt, salesName]);

  const sorted = useMemo(() => {
    if (sortMode === "alpha") {
      return [...filtered].sort((a, b) =>
        a.name.localeCompare(b.name, "da", { sensitivity: "base" }),
      );
    }
    if (sortMode === "last_visit") {
      return [...filtered].sort((a, b) => {
        const aT = a.extension?.last_visit_at ?? "";
        const bT = b.extension?.last_visit_at ?? "";
        return bT.localeCompare(aT);
      });
    }
    return [...filtered].sort((a, b) => comparePriority(a.priority, b.priority));
  }, [filtered, sortMode]);

  const [visibleCount, setVisibleCount] = useState(INITIAL_BATCH);
  const loadMoreRef = useRef<HTMLDivElement | null>(null);

  // Reset the reveal-window whenever the filtered/sorted set changes so
  // a linse-skifte doesn't leave us stranded deep into an old list.
  useEffect(() => {
    setVisibleCount(INITIAL_BATCH);
  }, [lens, distrikt, salesName, sortMode, onlyMine]);

  const visible = sorted.slice(0, visibleCount);
  const hasMore = visibleCount < sorted.length;

  // Reveal the next batch when the sentinel enters view. Uses a
  // 300 px root-margin so the next batch is already there before the
  // user hits bottom — flow bliver aldrig afbrudt af "vent på indlæs".
  useEffect(() => {
    if (!hasMore) return;
    const node = loadMoreRef.current;
    if (!node) return;
    const obs = new IntersectionObserver(
      (entries) => {
        for (const e of entries) {
          if (e.isIntersecting) {
            setVisibleCount((n) => Math.min(sorted.length, n + BATCH_STEP));
          }
        }
      },
      { rootMargin: "300px 0px" },
    );
    obs.observe(node);
    return () => obs.disconnect();
  }, [hasMore, sorted.length]);

  const isEmpty = !query.isLoading && !query.error && sorted.length === 0;

  return (
    <div className="mx-auto max-w-screen-2xl px-4 py-6">
      <header className="mb-5 flex flex-wrap items-baseline justify-between gap-3">
        <div>
          <div className="text-muted-foreground text-xs uppercase tracking-widest">
            {translate("lago.felt.dagens.title_today")}
          </div>
          <h1 className="mt-1 text-2xl font-semibold capitalize">
            {formatToday()}
          </h1>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <Button
            size="sm"
            variant={onlyMine ? "default" : "outline"}
            onClick={() => setOnlyMine((v) => !v)}
            disabled={mySalesId == null}
            className="h-8"
          >
            {translate("lago.customer_list.filter_mine")}
          </Button>
          <Select
            value={distrikt}
            onValueChange={setDistrikt}
          >
            <SelectTrigger className="h-8 w-auto text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value={ALL_SENTINEL}>
                {translate("lago.customer_list.filter_district_all")}
              </SelectItem>
              {distinctDistrikter.map((d) => (
                <SelectItem key={d} value={d}>
                  {d}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Select value={salesName} onValueChange={setSalesName}>
            <SelectTrigger className="h-8 w-auto text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value={ALL_SENTINEL}>
                {translate("lago.customer_list.filter_sales_all")}
              </SelectItem>
              {distinctSales.map((n) => (
                <SelectItem key={n} value={n}>
                  {n}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Select
            value={sortMode}
            onValueChange={(v) => setSortMode(v as SortMode)}
          >
            <SelectTrigger className="h-8 w-[200px] text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="most_overdue">
                {translate("lago.felt.dagens.sort.most_overdue")}
              </SelectItem>
              <SelectItem value="alpha">
                {translate("lago.felt.dagens.sort.alpha")}
              </SelectItem>
              <SelectItem value="last_visit">
                {translate("lago.felt.dagens.sort.last_visit")}
              </SelectItem>
            </SelectContent>
          </Select>
        </div>
      </header>

      <div className="mb-4 flex flex-wrap gap-2">
        <LensChip
          active={lens === "needs_now"}
          onClick={() => setLens("needs_now")}
          icon={<AlertCircle className="h-3.5 w-3.5" />}
          label={translate("lago.felt.dagens.lenses.needs_now")}
          count={counts.needs_now}
          tone="warn"
        />
        <LensChip
          active={lens === "planned_today"}
          onClick={() => setLens("planned_today")}
          icon={<CalendarClock className="h-3.5 w-3.5" />}
          label={translate("lago.felt.dagens.lenses.planned_today")}
          count={counts.planned_today}
        />
        <LensChip
          active={lens === "never_visited"}
          onClick={() => setLens("never_visited")}
          icon={<Sparkles className="h-3.5 w-3.5" />}
          label={translate("lago.felt.dagens.lenses.never_visited")}
          count={counts.never_visited}
        />
      </div>

      {query.isLoading ? (
        <div className="text-muted-foreground flex items-center gap-2 py-8 text-sm">
          <Loader2 className="h-4 w-4 animate-spin" />
          {translate("lago.customer_list.loading")}
        </div>
      ) : query.error ? (
        <p className="text-destructive py-4 text-sm">
          {translate("lago.customer_list.load_failed")}{" "}
          {(query.error as Error).message}
        </p>
      ) : isEmpty ? (
        <div className="text-muted-foreground rounded-md border border-dashed p-10 text-center text-sm">
          {lens === "needs_now"
            ? translate("lago.felt.dagens.empty_needs")
            : translate("lago.felt.dagens.empty_all_lens")}
        </div>
      ) : (
        <>
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-3">
            {visible.map((c) => (
              <CustomerCard key={c.id} customer={c} />
            ))}
          </div>
          {hasMore ? (
            <div
              ref={loadMoreRef}
              className="text-muted-foreground mt-6 flex items-center justify-center gap-2 py-6 text-xs"
              aria-live="polite"
            >
              <Loader2 className="h-4 w-4 animate-spin" />
              <span>
                {translate("lago.felt.dagens.page_size_hint", {
                  n: visible.length,
                  total: sorted.length,
                })}
              </span>
            </div>
          ) : (
            <div className="text-muted-foreground mt-6 text-center text-xs">
              {translate("lago.felt.dagens.page_size_hint", {
                n: visible.length,
                total: sorted.length,
              })}
            </div>
          )}
        </>
      )}
    </div>
  );
}

interface LensChipProps {
  active: boolean;
  onClick: () => void;
  icon: React.ReactNode;
  label: string;
  count: number;
  tone?: "warn";
}

function LensChip({ active, onClick, icon, label, count, tone }: LensChipProps) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "border-border inline-flex items-center gap-1.5 rounded-full border px-3 py-1 text-xs transition-colors",
        active
          ? "bg-foreground text-background border-foreground"
          : "hover:bg-muted bg-background",
      )}
    >
      {icon}
      <span>{label}</span>
      <span
        className={cn(
          "rounded-full px-1.5 py-px text-[10px] font-semibold",
          active
            ? "bg-background text-foreground"
            : tone === "warn"
              ? "bg-red-100 text-red-700"
              : "bg-muted text-foreground",
        )}
      >
        {count}
      </span>
    </button>
  );
}
