// ---------------------------------------------------------------------
// Kortfliser
//
// Dataforsyningens gratis Skærmkort-tjeneste er den langsigtede løsning
// (dansk, officielt) men kræver en gratis token registreret på
// https://dataforsyningen.dk/user/register. Når vi har token'et
// afsløres den via `VITE_DATAFORSYNINGEN_TOKEN` og vi bruger deres
// WMTS-endpoint. Uden token falder vi tilbage til CARTO's Positron —
// en pålidelig, gratis, tokenfri basemap-tjeneste bygget på OSM-data
// der virker fra github.io (uens `tile.openstreetmap.org`, som
// eksplicit rate-limiter apps og ofte tjener blank fra github.io).
// ---------------------------------------------------------------------

const DATAFORSYNINGEN_TOKEN = (import.meta.env.VITE_DATAFORSYNINGEN_TOKEN ?? "")
  .toString()
  .trim();

const CARTO_TILES = [
  "https://a.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png",
  "https://b.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png",
  "https://c.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png",
  "https://d.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png",
];

// Dataforsyningens Skærmkort_dæmpet WMTS bygges kun når token er sat.
const DATAFORSYNINGEN_TILES = DATAFORSYNINGEN_TOKEN
  ? [
      `https://api.dataforsyningen.dk/topo_skaermkort_daempet_DAF?service=WMTS&request=GetTile&version=1.0.0&layer=topo_skaermkort_daempet&tilematrixset=View1&style=default&format=image/jpeg&tilematrix={z}&tilecol={x}&tilerow={y}&token=${DATAFORSYNINGEN_TOKEN}`,
    ]
  : null;

const TILE_URLS = DATAFORSYNINGEN_TILES ?? CARTO_TILES;
const TILE_ATTRIBUTION = DATAFORSYNINGEN_TILES
  ? "© Styrelsen for Dataforsyning og Infrastruktur · geokodning: Dataforsyningen (DAWA)"
  : "© <a href=\"https://carto.com/attributions\">CARTO</a> · © OpenStreetMap-bidragydere · geokodning: Dataforsyningen (DAWA)";

const DK_CENTER: [number, number] = [10.5, 56.0];
const DK_ZOOM = 6.4;

// Radius i km for "Nær mig". Konstant som brief anbefaler (kan senere
// gøres til en indstilling i Settings).
const NEAR_ME_RADIUS_KM = 25;

const PIN_COLORS = {
  overdue: "#dc2626",
  soon: "#d97706",
  on_plan: "#059669",
  never_visited: "#9ca3af",
  A: "#7a1e2b",
  B: "#b8945e",
  C: "#4b5563",
  Aktiv: "#059669",
  Uafklaret: "#d97706",
  Passiv: "#9ca3af",
  Lead: "#2563eb",
  fallback: "#374151",
} as const;

function pinColor(mode: ColorMode, c: FeltCustomer): string {
  if (mode === "priority") return PIN_COLORS[c.priority.status];
  if (mode === "segment") {
    const seg = c.extension?.segment;
    if (seg === "A" || seg === "B" || seg === "C") return PIN_COLORS[seg];
    return PIN_COLORS.fallback;
  }
  // status
  const k = c.extension?.kundestatus;
  if (k?.includes("Aktiv")) return PIN_COLORS.Aktiv;
  if (k?.includes("Uafklaret")) return PIN_COLORS.Uafklaret;
  if (k?.includes("Passiv")) return PIN_COLORS.Passiv;
  if (k?.includes("Lead")) return PIN_COLORS.Lead;
  return PIN_COLORS.fallback;
}

function coordsOf(c: FeltCustomer): { lat: number; lng: number } | null {
  const ext = c.extension as
    | (FeltCustomer["extension"] & { _lat?: number; _lng?: number })
    | null;
  if (!ext || typeof ext._lat !== "number" || typeof ext._lng !== "number") {
    return null;
  }
  return { lat: ext._lat, lng: ext._lng };
}

/** Haversine — km mellem to koordinater. Bruges til "Nær mig". */
function haversineKm(
  a: { lat: number; lng: number },
  b: { lat: number; lng: number },
): number {
  const R = 6371;
  const dLat = ((b.lat - a.lat) * Math.PI) / 180;
  const dLng = ((b.lng - a.lng) * Math.PI) / 180;
  const s =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((a.lat * Math.PI) / 180) *
      Math.cos((b.lat * Math.PI) / 180) *
      Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(s));
}

interface Filters {
  onlyMine: boolean;
  segments: Set<"A" | "B" | "C">;
  distrikt: string | null;
  needsVisit: boolean;
  neverVisited: boolean;
  kundestatus: string | null;
}

const EMPTY_FILTERS: Filters = {
  onlyMine: false,
  segments: new Set(),
  distrikt: null,
  needsVisit: false,
  neverVisited: false,
  kundestatus: null,
};

export function KortPage() {
  const translate = useTranslate();
  const isMobile = useIsMobile();
  const { data: identity } = useGetIdentity();
  const mySalesId = typeof identity?.id === "number" ? identity.id : null;

  const [filters, setFilters] = useState<Filters>(EMPTY_FILTERS);
  const [colorMode, setColorMode] = useState<ColorMode>("priority");
  const [nearMe, setNearMe] = useState<{ lat: number; lng: number } | null>(
    null,
  );
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [totalMissing, setTotalMissing] = useState<number>(0);

  const intervals = useVisitIntervals();
  const query = useQuery({
    queryKey: [
      "lago-kort-customers",
      { onlyMine: filters.onlyMine, mySalesId, intervals },
    ],
    queryFn: () =>
      fetchKortCustomers({
        mySalesId,
        onlyMine: filters.onlyMine,
        intervals,
      }),
  });

  // Track how many customers *don't* have coordinates so we can hint the
  // sælger why counts don't add up.
  const totalQuery = useQuery({
    queryKey: ["lago-kort-total"],
    queryFn: async () => {
      const supabase = getSupabaseClient();
      const [total, missing] = await Promise.all([
        supabase
          .from("companies_lago")
          .select("company_id", { head: true, count: "exact" })
          .not("visma_customer_no", "is", null),
        supabase
          .from("companies_lago")
          .select("company_id", { head: true, count: "exact" })
          .not("visma_customer_no", "is", null)
          .or("lat.is.null,lng.is.null"),
      ]);
      return {
        total: total.count ?? 0,
        missing: missing.count ?? 0,
      };
    },
    staleTime: 60_000,
  });

  useEffect(() => {
    if (totalQuery.data) setTotalMissing(totalQuery.data.missing);
  }, [totalQuery.data]);

  const filtered = useMemo(() => {
    if (!query.data) return [];
    return query.data.filter((c) => {
      const ext = c.extension;
      if (filters.segments.size > 0) {
        if (!ext?.segment || !filters.segments.has(ext.segment)) return false;
      }
      if (filters.distrikt && ext?.distrikt !== filters.distrikt) return false;
      if (filters.kundestatus && ext?.kundestatus !== filters.kundestatus)
        return false;
      if (filters.needsVisit) {
        if (
          c.priority.status !== "overdue" &&
          c.priority.status !== "never_visited"
        )
          return false;
      }
      if (filters.neverVisited && c.priority.status !== "never_visited")
        return false;
      if (nearMe) {
        const coords = coordsOf(c);
        if (!coords) return false;
        if (haversineKm(nearMe, coords) > NEAR_ME_RADIUS_KM) return false;
      }
      return true;
    });
  }, [query.data, filters, nearMe]);

  const distinctDistrikter = useMemo(() => {
    const s = new Set<string>();
    for (const c of query.data ?? []) {
      if (c.extension?.distrikt) s.add(c.extension.distrikt);
    }
    return [...s].sort((a, b) => a.localeCompare(b, "da"));
  }, [query.data]);

  const distinctStatus = useMemo(() => {
    const s = new Set<string>();
    for (const c of query.data ?? []) {
      if (c.extension?.kundestatus) s.add(c.extension.kundestatus);
    }
    return [...s].sort((a, b) => a.localeCompare(b, "da"));
  }, [query.data]);

  const geojson = useMemo(() => {
    const features: unknown[] = [];
    for (const c of filtered) {
      const coord = coordsOf(c);
      if (!coord) continue;
      features.push({
        type: "Feature",
        properties: { id: c.id, color: pinColor(colorMode, c) },
        geometry: { type: "Point", coordinates: [coord.lng, coord.lat] },
      });
    }
    return { type: "FeatureCollection" as const, features };
  }, [filtered, colorMode]);

  const selected = useMemo(
    () => filtered.find((c) => c.id === selectedId) ?? null,
    [filtered, selectedId],
  );

  const askNearMe = useCallback(() => {
    if (nearMe) {
      setNearMe(null);
      return;
    }
    if (!("geolocation" in navigator)) return;
    navigator.geolocation.getCurrentPosition(
      (pos) => setNearMe({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
      () => {
        alert(translate("lago.felt.kort.near_me_geo_denied"));
      },
      { maximumAge: 60_000, timeout: 8_000 },
    );
  }, [nearMe, translate]);

  return (
    <div
      className="relative flex min-h-[560px] flex-1"
      style={{ height: "calc(100dvh - 180px)" }}
    >
      {!isMobile && (
        <aside className="border-r bg-background z-10 w-[260px] overflow-y-auto">
          <KortLensPanel
            colorMode={colorMode}
            onColorModeChange={setColorMode}
            filters={filters}
            onFiltersChange={setFilters}
            distinctDistrikter={distinctDistrikter}
            distinctStatus={distinctStatus}
            nearMeOn={nearMe != null}
            onToggleNearMe={askNearMe}
            hasMySalesId={mySalesId != null}
          />
        </aside>
      )}
      <div className="relative flex-1">
        <MapCanvas geojson={geojson} onPinTap={setSelectedId} />
        <div className="text-muted-foreground bg-background/95 pointer-events-none absolute top-3 left-1/2 -translate-x-1/2 rounded-full border px-3 py-1 text-xs shadow-sm">
          {translate("lago.felt.kort.showing", {
            shown: filtered.length,
            total: query.data?.length ?? 0,
          })}
          {totalMissing > 0 && (
            <>
              {" · "}
              <span className="text-amber-800">
                {translate("lago.felt.kort.no_coords_hint", {
                  smart_count: totalMissing,
                  missing: totalMissing,
                })}
              </span>
            </>
          )}
        </div>
        {isMobile && (
          <div className="absolute top-3 left-3 right-3 z-10 flex gap-1.5 overflow-x-auto rounded-full bg-background/95 p-1 shadow">
            <QuickChip
              on={filters.needsVisit}
              onClick={() =>
                setFilters((f) => ({ ...f, needsVisit: !f.needsVisit }))
              }
              label={translate("lago.felt.kort.color_priority")}
            />
            {(["A", "B", "C"] as const).map((s) => (
              <QuickChip
                key={s}
                on={filters.segments.has(s)}
                onClick={() =>
                  setFilters((f) => {
                    const next = new Set(f.segments);
                    next.has(s) ? next.delete(s) : next.add(s);
                    return { ...f, segments: next };
                  })
                }
                label={s}
              />
            ))}
            <Button
              size="sm"
              variant={nearMe ? "default" : "outline"}
              className="h-7 rounded-full px-2 text-xs"
              onClick={askNearMe}
            >
              <Compass className="h-3 w-3" />
              {nearMe ? translate("lago.felt.kort.near_me_off") : translate("lago.felt.kort.near_me")}
            </Button>
          </div>
        )}
        {query.isLoading && (
          <div className="text-muted-foreground bg-background/70 absolute inset-0 flex items-center justify-center gap-2 text-sm">
            <Loader2 className="h-4 w-4 animate-spin" />
            {translate("lago.felt.kort.loading")}
          </div>
        )}
        {query.error && (
          <div className="text-destructive bg-background/70 absolute inset-0 flex items-center justify-center gap-2 text-sm">
            <AlertCircle className="h-4 w-4" />
            {(query.error as Error).message}
          </div>
        )}
      </div>

      {isMobile ? (
        <Sheet
          open={selected != null}
          onOpenChange={(v) => !v && setSelectedId(null)}
        >
          <SheetContent side="bottom" className="max-h-[80vh] overflow-y-auto">
            <SheetHeader>
              <SheetTitle className="sr-only">
                {selected?.name ?? "Kunde"}
              </SheetTitle>
            </SheetHeader>
            {selected && (
              <div className="pt-2">
                <CustomerCard customer={selected} variant="list" />
              </div>
            )}
          </SheetContent>
        </Sheet>
      ) : (
        selected && (
          <aside className="border-l bg-background z-10 w-[380px] overflow-y-auto p-3">
            <div className="mb-2 flex items-center justify-between">
              <div className="text-muted-foreground text-xs uppercase tracking-widest">
                Kunde
              </div>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setSelectedId(null)}
              >
                {translate("lago.felt.kort.pin_close")} ×
              </Button>
            </div>
            <CustomerCard customer={selected} variant="list" />
          </aside>
        )
      )}
    </div>
  );
}

function QuickChip({
  on,
  onClick,
  label,
}: {
  on: boolean;
  onClick: () => void;
  label: string;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "shrink-0 rounded-full border px-2.5 py-1 text-[11px] font-medium",
        on ? "bg-foreground text-background border-foreground" : "border-border",
      )}
    >
      {label}
    </button>
  );
}

interface MapCanvasProps {
  geojson: { type: "FeatureCollection"; features: unknown[] };
  onPinTap: (id: number) => void;
}

function MapCanvas({ geojson, onPinTap }: MapCanvasProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<MapLibreMap | null>(null);
  // Kilde-af-sandhed for pin-features: en ref der altid holder den
  // nyeste geojson. Uden dette ville map.on('load')-callbacken bruge
  // sit closure-snapshot fra første render (typisk tom) — pins ville
  // aldrig blive tegnet efter query'en er resolvet.
  const geojsonRef = useRef(geojson);
  geojsonRef.current = geojson;
  // Klik-callback holdes også i en ref, så listener-registreringen
  // ikke re-runner effekten (og bygger nyt map) når parent renderer.
  const onPinTapRef = useRef(onPinTap);
  onPinTapRef.current = onPinTap;

  useEffect(() => {
    if (!containerRef.current || mapRef.current) return;
    const map = new maplibregl.Map({
      container: containerRef.current,
      style: {
        version: 8,
        sources: {
          basemap: {
            type: "raster",
            tiles: TILE_URLS,
            tileSize: 256,
            attribution: TILE_ATTRIBUTION,
          },
        },
        layers: [
          {
            id: "basemap",
            type: "raster",
            source: "basemap",
            minzoom: 0,
            maxzoom: 19,
          },
        ],
        // MapLibre kræver en glyphs-endpoint for at rendere tekst-labels
        // (fx tallet i cluster-cirklerne). OpenMapTiles' gratis font-
        // server virker fra github.io og har alle standard fontstacks
        // vi bruger. Uden dette kaster MapLibre inden kortet får rendered.
        glyphs: "https://fonts.openmaptiles.org/{fontstack}/{range}.pbf",
      } as any,
      center: DK_CENTER,
      zoom: DK_ZOOM,
      minZoom: 5,
      maxZoom: 17,
    });
    map.addControl(new maplibregl.NavigationControl({ showCompass: false }));
    map.addControl(
      new maplibregl.AttributionControl({ compact: true }),
      "bottom-right",
    );
    map.on("load", () => {
      map.addSource("customers", {
        type: "geojson",
        data: geojsonRef.current as any,
        cluster: true,
        clusterRadius: 40,
        clusterMaxZoom: 12,
      });
      map.addLayer({
        id: "clusters",
        type: "circle",
        source: "customers",
        filter: ["has", "point_count"],
        paint: {
          "circle-color": "#1e1b16",
          "circle-radius": [
            "step",
            ["get", "point_count"],
            18,
            10,
            22,
            50,
            28,
          ],
          "circle-opacity": 0.85,
          "circle-stroke-color": "#ffffff",
          "circle-stroke-width": 2,
        },
      });
      map.addLayer({
        id: "cluster-count",
        type: "symbol",
        source: "customers",
        filter: ["has", "point_count"],
        layout: {
          "text-field": ["get", "point_count_abbreviated"],
          "text-font": ["Noto Sans Regular"],
          "text-size": 12,
        },
        paint: { "text-color": "#ffffff" },
      });
      map.addLayer({
        id: "pins",
        type: "circle",
        source: "customers",
        filter: ["!", ["has", "point_count"]],
        paint: {
          "circle-color": ["get", "color"],
          "circle-radius": 8,
          "circle-stroke-color": "#ffffff",
          "circle-stroke-width": 2,
        },
      });

      map.on("click", "pins", (e) => {
        const feat = e.features?.[0];
        const id = feat?.properties?.id;
        if (typeof id === "number") onPinTapRef.current(id);
      });
      map.on("mouseenter", "pins", () => {
        map.getCanvas().style.cursor = "pointer";
      });
      map.on("mouseleave", "pins", () => {
        map.getCanvas().style.cursor = "";
      });

      map.on("click", "clusters", (e) => {
        const feat = e.features?.[0];
        const clusterId = feat?.properties?.cluster_id;
        const source = map.getSource("customers") as any;
        if (source?.getClusterExpansionZoom && clusterId != null) {
          source.getClusterExpansionZoom(
            clusterId,
            (err: unknown, zoom: number) => {
              if (err) return;
              const coords = (feat?.geometry as any).coordinates;
              map.easeTo({ center: coords, zoom });
            },
          );
        }
      });
      map.on("mouseenter", "clusters", () => {
        map.getCanvas().style.cursor = "pointer";
      });
      map.on("mouseleave", "clusters", () => {
        map.getCanvas().style.cursor = "";
      });
    });
    mapRef.current = map;

    // Genindlæs pin-source hvis map.load allerede har fyret før effekt-
    // kaldet (fx ved re-mount efter hot-reload).
    const onLoadResize = () => map.resize();
    map.on("load", onLoadResize);

    // Observere containeren så maplibre re-flow'er når panelet
    // slås til/fra eller sheet'en åbnes — ellers står kortet ofte i 0×0
    // efter en layoutændring.
    const ro = new ResizeObserver(() => {
      if (mapRef.current) mapRef.current.resize();
    });
    ro.observe(containerRef.current);

    return () => {
      ro.disconnect();
      map.remove();
      mapRef.current = null;
    };
    // Map opsættes én gang på mount. Klik-callback + geojson holdes i
    // refs (ovenfor), så de er altid friske uden at re-mounte kortet.
  }, []);

  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    const apply = () => {
      const src = map.getSource("customers") as any;
      if (src?.setData) src.setData(geojson);
    };
    // Hvis style-loaden endnu ikke er kørt, venter vi på 'load' —
    // ellers landede pin-data'en før source var oprettet og setData
    // ville bare returnere no-op.
    if (map.isStyleLoaded()) {
      apply();
    } else {
      map.once("load", apply);
    }
  }, [geojson]);

  return (
    <div
      ref={containerRef}
      className="absolute inset-0"
      style={{ width: "100%", height: "100%" }}
    />
  );
}
