import { CheckCircle2 } from "lucide-react";
import { useState } from "react";
import { useTranslate } from "ra-core";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { RegistrerModal } from "./RegistrerModal";
import type { TabKey } from "./RegistrerModal";

interface RegistrerButtonProps {
  companyId: number;
  companyName: string;
  variant?: "card" | "primary" | "large";
  initialTab?: TabKey;
  className?: string;
}

/**
 * Grøn primær Registrér-knap. Two visual variants:
 *  - `card` — stacked-icon 56 px target used inside the felt CustomerCard
 *    grid (replaces the old "✓ Besøgt").
 *  - `primary` — full-width filled row for the customer show
 *    RegistrationRail.
 *  - `large` — extra-wide filled row, used as the always-visible
 *    Registrér-CTA above the Rail på kundesiden 3c.
 */
export function RegistrerButton({
  companyId,
  companyName,
  variant = "primary",
  initialTab = "besoeg",
  className,
}: RegistrerButtonProps) {
  const translate = useTranslate();
  const [open, setOpen] = useState(false);

  const green =
    "bg-emerald-600 text-white hover:bg-emerald-700 focus-visible:ring-emerald-500/40";

  return (
    <>
      {variant === "card" ? (
        <Button
          variant="default"
          className={cn(
            "flex h-14 flex-col gap-0.5 rounded-md px-2 py-1 text-[11px]",
            green,
            className,
          )}
          onClick={() => setOpen(true)}
          aria-label={translate("lago.registrer.button")}
          title={translate("lago.registrer.button_hint")}
        >
          <CheckCircle2 className="h-4 w-4" />
          <span>{translate("lago.felt.card.action_register")}</span>
        </Button>
      ) : variant === "large" ? (
        <Button
          size="lg"
          className={cn(
            "h-12 w-full gap-2 text-base font-semibold",
            green,
            className,
          )}
          onClick={() => setOpen(true)}
        >
          <CheckCircle2 className="h-5 w-5" />
          {translate("lago.registrer.button")}
        </Button>
      ) : (
        <Button
          className={cn("w-full justify-start gap-2", green, className)}
          onClick={() => setOpen(true)}
        >
          <CheckCircle2 className="h-4 w-4" />
          {translate("lago.registrer.button")}
        </Button>
      )}

      <RegistrerModal
        open={open}
        onOpenChange={setOpen}
        companyId={companyId}
        companyName={companyName}
        initialTab={initialTab}
      />
    </>
  );
}
