import {
  DEFAULT_INTERVAL_DAYS,
  intervalForSegment,
  SEGMENT_INTERVAL_DAYS,
  SOON_RATIO,
  type Segment,
} from "./segmentIntervals";

export type VisitStatus = "overdue" | "soon" | "on_plan" | "never_visited";

export interface VisitPriority {
  status: VisitStatus;
  intervalDays: number;
  /** Days since the last visit. Null if there was never one. */
  daysSinceVisit: number | null;
  /**
   * Days past the expected interval. Positive = overdue; zero or negative =
   * on plan. Null when there was never a visit.
   */
  daysOverdue: number | null;
  /**
   * Sort key — bigger = more urgent. Customers without a visit get the
   * highest score so they bubble to the top.
   */
  sortScore: number;
}

/**
 * Runtime overrides for interval settings (brief 11). Loaded from
 * public.lago_settings.visit_intervals via useVisitIntervals(). When not
 * provided, the compile-time defaults from segmentIntervals.ts are used
 * so any code path that hasn't been wired up yet still works.
 */
export interface IntervalsConfig {
  intervalDays: Record<Segment, number>;
  soonRatio: number;
}

export const DEFAULT_INTERVALS_CONFIG: IntervalsConfig = {
  intervalDays: { ...SEGMENT_INTERVAL_DAYS },
  soonRatio: SOON_RATIO,
};

const MS_PER_DAY = 24 * 60 * 60 * 1000;

function pickIntervalDays(
  segment: Segment | null | undefined,
  config?: IntervalsConfig,
): number {
  if (!config) return intervalForSegment(segment);
  if (segment === "A" || segment === "B" || segment === "C") {
    return config.intervalDays[segment] ?? intervalForSegment(segment);
  }
  return config.intervalDays.B ?? DEFAULT_INTERVAL_DAYS;
}

export function computeVisitPriority(
  lastVisitISO: string | null | undefined,
  segment: Segment | null | undefined,
  now: Date = new Date(),
  config?: IntervalsConfig,
): VisitPriority {
  const intervalDays = pickIntervalDays(segment, config);
  const soonRatio = config?.soonRatio ?? SOON_RATIO;

  if (!lastVisitISO) {
    return {
      status: "never_visited",
      intervalDays,
      daysSinceVisit: null,
      daysOverdue: null,
      // Push never-visited above any numerically-overdue customer.
      sortScore: Number.POSITIVE_INFINITY,
    };
  }

  const last = new Date(lastVisitISO);
  const daysSinceVisit = Math.floor(
    (now.getTime() - last.getTime()) / MS_PER_DAY,
  );
  const daysOverdue = daysSinceVisit - intervalDays;

  let status: VisitStatus;
  if (daysOverdue > 0) {
    status = "overdue";
  } else if (daysSinceVisit >= intervalDays * soonRatio) {
    status = "soon";
  } else {
    status = "on_plan";
  }

  return {
    status,
    intervalDays,
    daysSinceVisit,
    daysOverdue,
    sortScore: daysOverdue,
  };
}

const STATUS_ORDER: Record<VisitStatus, number> = {
  never_visited: 0,
  overdue: 1,
  soon: 2,
  on_plan: 3,
};

/**
 * Comparator that puts the most urgent customer first:
 * never_visited → overdue (most overdue first) → soon → on_plan.
 */
export function comparePriority(a: VisitPriority, b: VisitPriority): number {
  const groupDelta = STATUS_ORDER[a.status] - STATUS_ORDER[b.status];
  if (groupDelta !== 0) return groupDelta;
  // Same status group → more overdue (higher sortScore) first.
  if (b.sortScore !== a.sortScore) {
    return b.sortScore - a.sortScore;
  }
  return 0;
}
