import { useQuery } from "@tanstack/react-query";
import { Map, Search, Target } from "lucide-react";
import { useEffect, useMemo } from "react";
import { Navigate, useLocation, useNavigate } from "react-router-dom";
import { useGetIdentity, useTranslate } from "ra-core";

import { useIsMobile } from "@/hooks/use-mobile";
import { cn } from "@/lib/utils";

import { fetchCustomerList } from "@/lago/customers/dataAccess";
import { computeVisitPriority } from "@/lago/customers/priority";
import { useVisitIntervals } from "@/lago/settings/useVisitIntervals";

import { DagensPage } from "./DagensPage";
import { KortPage } from "./kort/KortPage";
import { SoegPage } from "./SoegPage";

type Mode = "kort" | "dagens" | "soeg";

const STORAGE_KEY = "lago.felt.lastMode";

/**
 * Fase A · fladeskifter. Landscape/PC gets a segmented control at the
 * top of the felt-flade; portrait/mobile gets a bottom-tab-bar so
 * tommelfingerbetjening is honoured. Selected mode persists in
 * localStorage — sælgeren lander samme sted næste gang.
 *
 * Kort-fanen ("kommer snart") vises altid — synlighed matcher design-
 * referencen. Default landing = Dagens.
 */
export function FeltShell() {
  const location = useLocation();
  const navigate = useNavigate();
  const translate = useTranslate();
  const isMobile = useIsMobile();

  const mode = detectMode(location.pathname);
  const badge = useNeedsVisitBadge();

  useEffect(() => {
    if (mode) {
      try {
        window.localStorage.setItem(STORAGE_KEY, mode);
      } catch {
        /* localStorage blocked */
      }
    }
  }, [mode]);

  if (!mode) {
    // /felt without a mode — pick up last-used or default to Dagens.
    let last: Mode = "dagens";
    try {
      const stored = window.localStorage.getItem(STORAGE_KEY);
      if (stored === "kort" || stored === "dagens" || stored === "soeg") {
        last = stored;
      }
    } catch {
      /* ignore */
    }
    return <Navigate to={`/felt/${last}`} replace />;
  }

  return (
    <div className="flex min-h-[calc(100vh-120px)] flex-col">
      {!isMobile && (
        <div className="bg-background sticky top-0 z-10 border-b">
          <div className="mx-auto flex max-w-screen-2xl items-center justify-center gap-2 px-4 py-2">
            <SegmentTab
              active={mode === "kort"}
              icon={<Map className="h-4 w-4" />}
              label={translate("lago.felt.tabs.kort")}
              onClick={() => navigate("/felt/kort")}
            />
            <SegmentTab
              active={mode === "dagens"}
              icon={<Target className="h-4 w-4" />}
              label={translate("lago.felt.tabs.dagens")}
              badge={badge}
              onClick={() => navigate("/felt/dagens")}
            />
            <SegmentTab
              active={mode === "soeg"}
              icon={<Search className="h-4 w-4" />}
              label={translate("lago.felt.tabs.soeg")}
              onClick={() => navigate("/felt/soeg")}
            />
          </div>
        </div>
      )}

      <div className={cn("flex-1", isMobile && "pb-16")}>
        {mode === "kort" && <KortPage />}
        {mode === "dagens" && <DagensPage />}
        {mode === "soeg" && <SoegPage />}
      </div>

      {isMobile && (
        <nav className="bg-background fixed inset-x-0 bottom-0 z-20 border-t">
          <div className="grid grid-cols-3 text-center">
            <BottomTab
              active={mode === "kort"}
              icon={<Map className="h-5 w-5" />}
              label={translate("lago.felt.tabs.kort")}
              onClick={() => navigate("/felt/kort")}
              muted
            />
            <BottomTab
              active={mode === "dagens"}
              icon={<Target className="h-5 w-5" />}
              label={translate("lago.felt.tabs.dagens")}
              badge={badge}
              onClick={() => navigate("/felt/dagens")}
            />
            <BottomTab
              active={mode === "soeg"}
              icon={<Search className="h-5 w-5" />}
              label={translate("lago.felt.tabs.soeg")}
              onClick={() => navigate("/felt/soeg")}
            />
          </div>
        </nav>
      )}
    </div>
  );
}

function detectMode(pathname: string): Mode | null {
  if (pathname === "/felt" || pathname === "/felt/") return null;
  if (pathname.startsWith("/felt/kort")) return "kort";
  if (pathname.startsWith("/felt/dagens")) return "dagens";
  if (pathname.startsWith("/felt/soeg")) return "soeg";
  return null;
}

function useNeedsVisitBadge(): number {
  const { data: identity } = useGetIdentity();
  const mySalesId = typeof identity?.id === "number" ? identity.id : null;
  const query = useQuery({
    queryKey: ["lago-customer-list", { onlyMine: true, mySalesId }],
    queryFn: () => fetchCustomerList({ mySalesId, onlyMine: true }),
    enabled: mySalesId != null,
  });
  const intervals = useVisitIntervals();
  return useMemo(() => {
    if (!query.data) return 0;
    let n = 0;
    for (const r of query.data) {
      const p = computeVisitPriority(
        r.extension?.last_visit_at,
        r.extension?.segment,
        new Date(),
        intervals,
      );
      if (p.status === "overdue" || p.status === "never_visited") n++;
    }
    return n;
  }, [query.data, intervals]);
}

interface SegmentTabProps {
  active: boolean;
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
  badge?: number;
  muted?: boolean;
}

function SegmentTab({
  active,
  icon,
  label,
  onClick,
  badge,
  muted,
}: SegmentTabProps) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "inline-flex items-center gap-2 rounded-full border px-4 py-1.5 text-sm transition-colors",
        active
          ? "bg-foreground text-background border-foreground"
          : "border-border hover:bg-muted bg-background text-foreground",
        muted && !active && "text-muted-foreground italic",
      )}
    >
      {icon}
      <span>{label}</span>
      {badge != null && badge > 0 && (
        <span
          className={cn(
            "rounded-full px-1.5 py-px text-[10px] font-semibold",
            active ? "bg-background text-red-700" : "bg-red-100 text-red-700",
          )}
        >
          {badge}
        </span>
      )}
    </button>
  );
}

function BottomTab({ active, icon, label, onClick, badge, muted }: SegmentTabProps) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "flex flex-col items-center justify-center gap-0.5 py-2 text-[11px]",
        active
          ? "text-foreground font-semibold"
          : "text-muted-foreground",
        muted && !active && "italic",
      )}
    >
      <div className="relative">
        {icon}
        {badge != null && badge > 0 && (
          <span className="absolute -right-2 -top-1 rounded-full bg-red-600 px-1.5 py-px text-[9px] font-bold text-white">
            {badge}
          </span>
        )}
      </div>
      <span>{label}</span>
    </button>
  );
}
